CREATE TABLE "categories" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "color_argb" INTEGER NOT NULL DEFAULT 4286549133, "sort_order" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "exercises" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "category_id" INTEGER NOT NULL REFERENCES categories (id), "type" INTEGER NOT NULL DEFAULT 0, "notes" TEXT NULL, "default_rest_time_seconds" INTEGER NULL, "is_favourite" INTEGER NOT NULL DEFAULT 0 CHECK ("is_favourite" IN (0, 1)), "archived" INTEGER NOT NULL DEFAULT 0 CHECK ("archived" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "exercise_multipliers" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "exercise_id" INTEGER NOT NULL REFERENCES exercises (id), "label" TEXT NOT NULL, "factor" REAL NOT NULL DEFAULT 1.0, "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "workout_sets" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "exercise_id" INTEGER NOT NULL REFERENCES exercises (id), "date" TEXT NOT NULL, "raw_weight" REAL NOT NULL DEFAULT 0.0, "weight_multiplier" REAL NOT NULL DEFAULT 1.0, "reps" INTEGER NOT NULL DEFAULT 0, "distance" REAL NOT NULL DEFAULT 0.0, "duration_seconds" INTEGER NOT NULL DEFAULT 0, "is_complete" INTEGER NOT NULL DEFAULT 0 CHECK ("is_complete" IN (0, 1)), "note" TEXT NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE "workout_day_notes" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "date" TEXT NOT NULL UNIQUE, "comment" TEXT NOT NULL);
CREATE TABLE "pr_reset_markers" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "date" TEXT NOT NULL, "note" TEXT NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE "app_settings" ("id" INTEGER NOT NULL DEFAULT 1, "theme_mode" INTEGER NOT NULL DEFAULT 0, "first_day_of_week" INTEGER NOT NULL DEFAULT 1, "default_weight_increment" REAL NOT NULL DEFAULT 2.5, "rest_timer_seconds" INTEGER NOT NULL DEFAULT 60, "rest_timer_vibrate" INTEGER NOT NULL DEFAULT 0 CHECK ("rest_timer_vibrate" IN (0, 1)), "rest_timer_sound" INTEGER NOT NULL DEFAULT 1 CHECK ("rest_timer_sound" IN (0, 1)), "rest_timer_auto_start" INTEGER NOT NULL DEFAULT 0 CHECK ("rest_timer_auto_start" IN (0, 1)), "track_personal_records" INTEGER NOT NULL DEFAULT 1 CHECK ("track_personal_records" IN (0, 1)), "mark_sets_complete" INTEGER NOT NULL DEFAULT 0 CHECK ("mark_sets_complete" IN (0, 1)), "keep_screen_on" INTEGER NOT NULL DEFAULT 0 CHECK ("keep_screen_on" IN (0, 1)), "estimated1rm_max_reps" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
PRAGMA user_version = 1;
